import { resolveOverlayBaseUrl } from '../../common/runtime-config';
import { bulbFontFace } from './styles';

const STYLE_ID = 'rgai-brand-font';

/** The brand font's declaration, as it goes in the page (files at the overlay host's root, a contract). */
export function brandFontCss(overlayBaseUrl: string): string {
  return bulbFontFace('RealGoodFont', overlayBaseUrl);
}

/**
 * Declares the brand font in the page itself, once. It has to be there: browsers ignore a @font-face inside a Shadow
 * DOM. <rg-bulb> calls this, so the font works on any page the bulb is placed on, not only on the campaign pages.
 */
export function ensureBrandFont(doc: Document = document): void {
  if (doc.getElementById(STYLE_ID)) return;
  const style = doc.createElement('style');
  style.id = STYLE_ID;
  style.textContent = brandFontCss(resolveOverlayBaseUrl());
  doc.head.appendChild(style);
}
