import { BaseElement } from '../../common/base-element';
import { ensureBrandFont } from './brand-font';
import { fetchProgress } from '../api';
import { createBulbController, type BulbController } from './controller';
import {
  BULB_GLASS_BOTTOM,
  BULB_GLASS_TOP,
  BULB_PALETTE,
  BULB_WIDTH_SAMPLES,
  calculateLap,
  createBulbGeometry,
  paletteColorOf,
} from './geometry';
import { bulbCss } from './styles';
import { bulbIds, bulbSvg } from './svg';

let instances = 0;
const geometry = createBulbGeometry(BULB_WIDTH_SAMPLES, BULB_GLASS_TOP, BULB_GLASS_BOTTOM);

/**
 * <rg-bulb slug="my-campaign">: the campaign's progress as the Real Good AI bulb. It re-reads the
 * totals once a minute. It declares the brand font in the page itself (brand-font.ts).
 */
export class RgBulb extends BaseElement {
  static get observedAttributes(): string[] {
    return ['slug'];
  }

  private readonly uid = `rg-bulb-${instances++}`;
  private poll: ReturnType<typeof setInterval> | undefined;
  private controller: BulbController | undefined;
  private started = false;

  constructor() {
    // `display: contents`: the host adds no box of its own, so the anchor lays out exactly as the
    // production markup's did (a plain <a> in whatever contains it).
    super(`:host { display: contents; }\n${bulbCss({ root: '.bulb-widget', fontFamily: '"RealGoodFont"', keyframes: 'bulb' })}`);
  }

  connectedCallback(): void {
    ensureBrandFont(); // the amount's font: declared in the page, whatever page the bulb is on
    this.start();
  }

  disconnectedCallback(): void {
    this.started = false;
    this.stop();
  }

  attributeChangedCallback(): void {
    if (this.started) this.start();
  }

  private start(): void {
    this.started = true;
    this.stop();
    const slug = this.getAttribute('slug');
    if (!slug) return;

    const ids = bulbIds(this.uid);
    this.setHtml(`
      <a class="bulb-widget" href="${window.location.origin}/fundraising-campaigns/p/${encodeURIComponent(slug)}" target="_blank" rel="noopener" aria-label="Campaign donation progress — click to view campaign">
        <div class="bulb-card">
          <div class="bulb-wiggle-wrap">${bulbSvg(ids)}</div>
        </div>
      </a>`);
    const byId = (id: string) => this.root.getElementById(id) as unknown as SVGElement;
    this.controller = createBulbController(
      {
        wiggle: this.$('.bulb-wiggle-wrap') as Element,
        baseFill: byId(ids.baseFill),
        liquid: byId(ids.liquid),
        waveA: byId(ids.waveA),
        waveB: byId(ids.waveB),
        amount: byId(ids.amount) as unknown as SVGTextElement,
      },
      { geometry, palette: BULB_PALETTE, calculateLap, paletteColorOf },
    );

    // DESIGN RULE (user, 2026-11-05): embedded and on-page bulbs POLL once a minute and must not
    // subscribe to Realtime: they can have many clients and a realtime connection costs more per
    // client. Only the stream overlay (few clients) uses Realtime. Do not "fix" this.
    const tick = () => {
      fetchProgress([slug])
        .then((rows) => {
          // No row (hidden or deleted campaign): keep what is shown rather than showing an error.
          if (rows.length) this.controller?.render(rows[0].raised_cents, rows[0].goal_cents);
        })
        .catch((err) => console.error('Bulb widget error:', err));
    };
    tick();
    this.poll = setInterval(tick, 60000);
  }

  private stop(): void {
    clearInterval(this.poll);
  }
}

if (!customElements.get('rg-bulb')) customElements.define('rg-bulb', RgBulb);
