import type { BulbColors, BulbGeometry } from './geometry';

/** The SVG elements the controller animates. */
export interface BulbElements {
  /** Gets the "wiggling" class on each lap. */
  wiggle: Element;
  /** Fill shown behind the glass during a lap > 0 (the previous lap's color). */
  baseFill: Element;
  /** Translated up and down to set the liquid level. */
  liquid: HTMLElement | SVGElement;
  waveA: Element;
  waveB: Element;
  /** The dollar amount. */
  amount: SVGTextElement | (Element & { getBBox(): { width: number } });
}

export interface BulbControllerDeps {
  geometry: BulbGeometry;
  palette: readonly BulbColors[];
  /** `calculateLap` from geometry.ts, passed in so this function has no free variables. */
  calculateLap(raised: number, goal: number): { lap: number; fraction: number };
  /** `paletteColorOf` from geometry.ts, for the same reason. */
  paletteColorOf(palette: readonly BulbColors[], index: number): BulbColors;
  /** The widest the amount text may be, in SVG units. */
  maxTextWidth?: number;
  /** How long the liquid takes to rise (matches the CSS transition). */
  animationMs?: number;
  /** When false, the bulb never wiggles (the overlay's `wiggle=0`). Default true. */
  wiggle?: boolean;
}

export interface BulbController {
  /** Show these totals (cents). Handles laps, colors and the amount text. */
  render(raisedCents: number, goalCents: number): void;
  /** Wiggle the bulb once (also used by the overlay on every donation). */
  wiggle(): void;
}

/**
 * The bulb's state machine: liquid level, laps and the dollar amount. It is the one copy used
 * by <rg-bulb>, the embed snippet and the stream overlay.
 *
 * It has NO free variables (everything comes from `els` and `deps`; only built-ins such as
 * Math, Promise, setTimeout and requestAnimationFrame are used), because the embed snippet
 * contains this function's source text.
 */
export function createBulbController(els: BulbElements, deps: BulbControllerDeps): BulbController {
  const MAX_TEXT_WIDTH = deps.maxTextWidth || 300;
  const ANIMATION_MS = deps.animationMs || 1100;
  const wiggleEnabled = deps.wiggle !== false;
  const state: {
    lap: number | null;
    isTransitioning: boolean;
    pendingData: { raised: number; goal: number } | null;
    lastRenderedText: string | null;
  } = { lap: null, isTransitioning: false, pendingData: null, lastRenderedText: null };

  const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
  const nextFrame = () => new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));

  els.wiggle.addEventListener('animationend', () => els.wiggle.classList.remove('wiggling'));

  function wiggle(): void {
    if (!wiggleEnabled) return;
    els.wiggle.classList.remove('wiggling');
    // Force a reflow so the animation restarts on back-to-back wiggles.
    void (els.wiggle as HTMLElement).offsetWidth;
    els.wiggle.classList.add('wiggling');
  }

  function applyColors(lap: number): void {
    const current = deps.paletteColorOf(deps.palette, lap);
    els.waveA.setAttribute('fill', current.a);
    els.waveB.setAttribute('fill', current.b);
    els.baseFill.setAttribute('fill', lap > 0 ? deps.paletteColorOf(deps.palette, lap - 1).a : 'none');
  }

  function setLiquidFraction(fraction: number, instant?: boolean): void {
    els.liquid.style.transition = instant ? 'none' : '';
    els.liquid.style.transform = 'translateY(' + deps.geometry.liquidSurfaceY(fraction) + 'px)';
    // Meant to force a reflow before the transition comes back (a no-op on an SVG <g>, as in the original).
    if (instant) void (els.liquid as unknown as HTMLElement).offsetHeight;
  }

  // Renders at 100px, measures, and shrinks to fit the glass.
  function updateAmountText(raisedCents: number): void {
    const text = '$' + Math.round(raisedCents / 100).toLocaleString();
    if (text === state.lastRenderedText) return;
    els.amount.textContent = text;
    let size = 100;
    (els.amount as unknown as HTMLElement).style.fontSize = size + 'px';
    try {
      const bbox = (els.amount as unknown as SVGTextElement).getBBox();
      if (bbox.width > MAX_TEXT_WIDTH) {
        size = Math.max(40, Math.floor(size * (MAX_TEXT_WIDTH / bbox.width)));
        (els.amount as unknown as HTMLElement).style.fontSize = size + 'px';
      }
    } catch {
      // not rendered (for example display: none): nothing to fit
    }
    state.lastRenderedText = text;
  }

  // Fill to the top, swap color, wiggle, drop to empty, then rise to the new fraction. Data that
  // arrives meanwhile is kept and used instead of being dropped.
  async function runBoundarySequence(targetLap: number, targetFraction: number): Promise<void> {
    state.isTransitioning = true;
    setLiquidFraction(1);
    await wait(ANIMATION_MS);
    applyColors(targetLap);
    wiggle();
    setLiquidFraction(0, true);
    await nextFrame();
    await nextFrame();
    const current = state.pendingData;
    if (current) {
      updateAmountText(current.raised);
      state.pendingData = null;
    }
    const target = current ? deps.calculateLap(current.raised, current.goal) : { lap: targetLap, fraction: targetFraction };
    state.lap = target.lap;
    setLiquidFraction(target.fraction);
    await wait(ANIMATION_MS);
    state.isTransitioning = false;
    if (state.pendingData) {
      const queued = state.pendingData;
      state.pendingData = null;
      render(queued.raised, queued.goal);
    }
  }

  function render(raisedCents: number, goalCents: number): void {
    updateAmountText(raisedCents);
    if (state.isTransitioning) {
      state.pendingData = { raised: raisedCents, goal: goalCents };
      return;
    }
    const r = deps.calculateLap(raisedCents, goalCents);
    if (state.lap !== null && r.lap > state.lap) {
      void runBoundarySequence(r.lap, r.fraction);
    } else {
      applyColors(r.lap);
      setLiquidFraction(r.fraction);
      state.lap = r.lap;
    }
  }

  return { render, wiggle };
}
