// CSS of the bulb widget, parameterized so one source serves three places:
//   - <rg-bulb> (Shadow DOM; root ".bulb-widget", the font is declared page-wide by the loader),
//   - the copy-paste embed snippet (root "#<id>", its own uniquely named font and keyframes,
//     because it runs on someone else's page),
//   - the stream overlay (see src/stream-overlay).
// The rules are production's, copied verbatim; only the selectors' roots and names vary.

export interface BulbCssOptions {
  /** Selector of the root element (the <a>): ".bulb-widget" or "#my-id". */
  root: string;
  /** Value of font-family for the amount, e.g. `"RealGoodFont"`. */
  fontFamily: string;
  /** Prefix of the keyframe names, so several copies never share animations. */
  keyframes: string;
  /** Width of the card in px (the widget is 220; the overlay shows it at 330). */
  cardWidth?: number;
  /** Also set a system font on the root, for the standalone snippet. */
  rootFont?: boolean;
}

export function bulbCss(o: BulbCssOptions): string {
  const { root, fontFamily, keyframes: kf } = o;
  const rootFont = o.rootFont
    ? ' font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;'
    : '';
  return `
  ${root} { display: inline-block; text-align: center; text-decoration: none; color: inherit; -webkit-tap-highlight-color: transparent;${rootFont} }
  ${root} .bulb-card { width: ${o.cardWidth ?? 220}px; transition: transform 0.15s ease; }
  ${root}:hover .bulb-card { transform: scale(1.03); }
  ${root} svg { display: block; width: 100%; height: auto; overflow: visible; }
  ${root} .bulb-amount-text {
    font-family: ${fontFamily}, "Arial Black", sans-serif;
    font-weight: 800;
    fill: #1c2b3a;
    stroke: #fff8e7;
    stroke-width: 7px;
    paint-order: stroke;
    pointer-events: none;
    user-select: none;
  }
  @keyframes ${kf}-wiggle {
    0%, 100% { transform: rotate(0deg); }
    20% { transform: rotate(-7deg); }
    40% { transform: rotate(6deg); }
    60% { transform: rotate(-4deg); }
    80% { transform: rotate(2deg); }
  }
  ${root} .bulb-wiggle-wrap.wiggling { animation: ${kf}-wiggle 0.6s ease; }
  @keyframes ${kf}-wave-a { from { transform: translateX(0); } to { transform: translateX(-100px); } }
  @keyframes ${kf}-wave-b { from { transform: translateX(0); } to { transform: translateX(85px); } }
  ${root} .bulb-wave-layer-a { animation: ${kf}-wave-a 3.4s linear infinite; }
  ${root} .bulb-wave-layer-b { animation: ${kf}-wave-b 5s linear infinite; }
  ${root} .bulb-liquid-level { transition: transform 1.1s cubic-bezier(0.4, 0, 0.2, 1); }
`;
}

/** The brand font, declared from the overlay host's root (the files live there; see CLAUDE.md). */
export function bulbFontFace(family: string, baseUrl: string): string {
  return `
  @font-face {
    font-family: "${family}";
    src: url("${baseUrl}/RealGoodFont-Regular.otf") format("opentype"),
         url("${baseUrl}/RealGoodFont-Regular.ttf") format("truetype");
    font-display: swap;
  }
`;
}
